/* Unit 2 — Guide 2: Building work tools and systems with Python on Windows (book pages 17–23). */
"use strict";
(function (A) {
  const bp = (p, ar, en) => ({ p, ar, en });
  const L = (k, ar, en) => ({ k, ar, en });
  A.lessons = (A.lessons || []).concat([
    {
      id: "y1", unit: "u5", pages: [17], diff: 2, min: 8, scene: "spec", related: ["p1", "p10", "y2"], pre: ["p10"],
      title: { ar: "قبل ما تطلب برنامج، اكتب بالضبط هو المفروض يعمل إيه", en: "Describe the process, not the code: the task spec" },
      sum: { ar: "طلب زي «عايز أداة تدمج الملفات» ناقصه أهم حاجة: أنهي ملفات؟ وإيه اللي يحصل لو فيه عمود ناقص أو صف متكرر؟ المواصفة الواضحة بتحسم ده قبل ما يتكتب سطر كود.", en: "Three ideas that govern everything after, and five elements before writing any line — tests above all." },
      book: [
        bp(17, "دلوقتي أي موظف — من غير خلفية برمجة — يقدر يطلب من الذكاء الاصطناعي يبني أداة ((python|بايثون)) تنفّذ مهمة متكررة على جهازه، وبعدين تحلّل النتائج، وبعدين تعرضها في تقرير تفاعلي أي زميل يفتحه بنقرة واحدة.", "Any employee — with no coding background — can now ask AI to build a ((python|Python)) tool that runs a recurring task on their PC, analyses the results, and shows them in an interactive report any colleague opens with one click."),
        bp(17, "**المبدأ**: المهارة المطلوبة مش كتابة الكود، لكن وصف العملية بوضوح وقابل للتنفيذ — زي ما بتحكيها لموظف جديد. **البنية**: تلات مستويات ورا بعض: أتمتة التشغيل، وبعدين التحليل، وبعدين العرض الإداري. **الحد الفاصل**: ماتبنيش أداة إلا لمهمة متكررة، قواعدها ثابتة، ونتيجتها ممكن التحقق منها.", "**Principle**: the skill isn’t writing code but describing the process precisely and actionably — as you would to a new employee. **Structure**: three consecutive levels: run automation, then analysis, then executive reporting. **Boundary**: build a tool only for a recurring task with stable rules and a verifiable result."),
        bp(17, "مواصفة المهمة — أهم خطوة في المشروع وأكتر خطوة بتتهمل: **المشكلة** (بالدقائق مش بالتخمين) · **المدخلات** (البنية الحقيقية مش المثالية) · **القواعد** (زي ما بتتطبق فعلًا مع كل استثناء) · **النتيجة** (الشكل بالظبط ومين يستلمها) · **الاختبارات** (أهم الخمسة).", "The task spec — the project’s most important step and the easiest to skip: **problem** (in minutes, not guesses) · **inputs** (real structure, not ideal) · **rules** (as actually applied, with every exception) · **result** (exact shape and who receives it) · **tests** (the most important of the five)."),
        bp(17, "غياب العنصر الخامس هو أكتر سبب شائع لفشل الأدوات اللي الذكاء الاصطناعي بيساعد في بنائها: الأداة شكلها شغالة، بس محدش عارف إمتى النتيجة بتطلع غلط. **لما تحدد الاختبارات قبل البناء** بتحوّل «كود شكله صح» لأداة تقدر تعتمد عليها كل شهر.", "Missing the fifth element is the commonest cause of failure in AI-built tools: the tool seems to work, but nobody knows when its result is wrong. **Defining tests before building** turns “code that looks right” into a tool you can rely on monthly."),
      ],
      levels: {
        simple: [
          L("what", "قبل ما تطلب أداة، اكتب «ورقة مواصفات» من خمسة أسطر: إيه المشكلة؟ إيه الملفات؟ إيه القواعد؟ شكل النتيجة إيه؟ وإزاي أعرف إنها صح؟\n\nزي طلب عرض سعر من مورّد: لو كتبت «عايزين خامة كويسة» هيبعت اللي عنده. لو حددت المواصفات والكمية والميزانية وطريقة الفحص عند الاستلام، هيبعت المطلوب بالظبط.", "Before asking for a tool, write a five-line “spec sheet”: what’s the problem? which files? what rules? what result? how will I know it’s right?\n\nLike requesting a quotation from a supplier: “good material” gets you whatever they stock. Specifications, quantity, budget and the acceptance check get you exactly what you need."),
          L("why", "لأن الذكاء الاصطناعي بيكتب الكود بسرعة، بس مش عارف قواعد شغلك واستثناءاتها. المواصفة بتنقل له المعرفة دي، والاختبارات بتحميك من أداة «شكلها» صح.", "Because AI writes code fast but doesn’t know your business rules and exceptions. The spec transfers that knowledge, and the tests protect you from a tool that only “looks” right."),
        ],
        mech: [
          L("how", "كل عنصر بيقفل نوع فشل:\n- **المشكلة بالدقائق** ← تعرف تستاهل الأتمتة أصلًا ولا لأ.\n- **المدخلات الحقيقية** ← الكود ما يفترضش أعمدة مش موجودة.\n- **القواعد مع الاستثناءات** ← الأداة ما تنهارش عند أول حالة غريبة.\n- **النتيجة بالظبط** ← المخرج يوصل للشخص الصح بالشكل الصح.\n- **الاختبارات** ← تعرف إمتى النتيجة بتطلع غلط.", "Each element closes a type of failure:\n- **Problem in minutes** → you know if it’s worth automating.\n- **Real inputs** → the code doesn’t assume missing columns.\n- **Rules with exceptions** → it doesn’t crash on the first odd case.\n- **Exact result** → the output reaches the right person in the right shape.\n- **Tests** → you know when the result is wrong."),
          L("link", "المواصفة هي المعادلة الحاكمة ([[p1]]) بصيغة هندسية، والاختبارات هي «اختبر الحالات الاستثنائية» ([[p2]]) و«خمس حالات اختبار» في الـ Prompt الذهبي ([[p10]]).", "The spec is the governing equation ([[p1]]) in engineering form, and the tests are “test the edge cases” ([[p2]]) and the golden prompt’s “five test cases” ([[p10]])."),
        ],
        practice: [
          L("example", "**المشكلة**: تجميع حضور الموظفين من 4 فروع بياخد 3 ساعات أسبوعيًا. **المدخلات**: 4 ملفات إكسل باسم الفرع، أعمدة: رقم الموظف، التاريخ، الدخول، الخروج. **القواعد**: التأخير بعد 15 دقيقة؛ الإجازة الرسمية مش بتتحسب غياب. **النتيجة**: ملف واحد لكل إدارة يتبعت للمدير. **الاختبارات**: موظف من غير خروج، يوم إجازة رسمية، موظف في فرعين، ملف ناقص.", "**Problem**: compiling attendance from 4 branches takes 3 hours a week. **Inputs**: 4 Excel files named by branch; columns: employee ID, date, in, out. **Rules**: late after 15 minutes; public holidays aren’t absences. **Result**: one file per department sent to its manager. **Tests**: an employee with no clock-out, a public holiday, an employee in two branches, a missing file."),
          L("apply", "اكتب مواصفة لمهمة واحدة من شغلك بالعناصر الخمسة في «ملاحظاتي». ركّز على الاختبارات: اكتب تلات حالات على الأقل تكون عارف نتيجتها الصح مسبقًا.", "Write a five-element spec for one task in “My notes”. Focus on the tests: at least three cases whose correct result you already know."),
        ],
        adv: [
          L("mistakes", "- **وصف الملف المثالي مش الحقيقي**: الملف الحقيقي فيه صفوف فاضية وأسماء مختلفة.\n- **نسيان الاستثناءات** لأنها «نادرة» — النادر بيحصل كل شهر.\n- **من غير اختبارات**: هتكتشف الغلط بعد تلات شهور في تقرير الإدارة.", "- **Describing the ideal file, not the real one**: real files have blank rows and odd names.\n- **Forgetting exceptions** because they’re “rare” — rare happens monthly.\n- **No tests**: you find the error three months later in a management report."),
          L("whennot", "لو مش قادر تكتب القواعد لأنها بتتغير كل مرة، المهمة مش بتحقق شرط «الثبات» وهتفضل أسرع بالإيد ([[y2]]).", "If you can’t write the rules because they change every time, the task fails the “stability” test and stays faster by hand ([[y2]])."),
        ],
      },
    },
    {
      id: "y2", unit: "u5", pages: [17, 18], diff: 2, min: 7, scene: "compass", lab: "worth", related: ["y1", "y3", "p12"], pre: ["y1"],
      title: { ar: "هل كل مهمة متكررة تستاهل برنامج؟", en: "Decision compass: when does a task deserve a tool?" },
      sum: { ar: "مش كل مهمة متكررة تستاهل برنامج. اضرب وقت المهمة في عدد مرات تكرارها، وقارن الناتج بوقت بناء الأداة وصيانتها، وبعدين قرر.", en: "Four questions decide whether automation is worth it, and four engineering rules protect the tool from rebuilds." },
      book: [
        bp(17, "قبل أي طلب للذكاء الاصطناعي: أربعة أسئلة بتحدد الأتمتة تستاهل الوقت فعلًا ولا لأ، وأربع قواعد بتحمي الأداة من إعادة البناء بعد أول تعديل.", "Before any AI request: four questions decide whether automation is really worth the time, and four rules protect the tool from a rebuild after the first change."),
        bp(17, "**التكرار**: بتتنفّذ أسبوعي أو أكتر، أو شهري بس بتاخد ساعات. **الثبات**: قواعدها مش بتتغير والاستثناءات محدودة وتقدر تحصرها. **كلفة الغلط بالإيد**: النسخ واللصق بيطلّع أخطاء صامتة ما بتتكتشف غير بعد ما يفوت الوقت. **إمكانية التحقق**: تقدر تقارن ناتج الأداة بناتج يدوي معروف ولو مرة.", "**Frequency**: weekly or more, or monthly but taking hours. **Stability**: rules don’t change; exceptions are few and listable. **Manual error cost**: copy-paste creates silent errors found too late. **Verifiability**: the output can be compared with a known manual result, even once."),
        bp(17, "**ماتلمسش البيانات الأصلية**: كل معالجة بتتكتب في نسخة أو مجلد ناتج منفصل. **سجل تشغيل مكتوب**: إيه اللي اتقرا، وكم صف، وإيه اللي اتستبعد وليه، وزمن التنفيذ — سطر لكل تشغيل.", "**Never touch the original data**: every process writes to a copy or a separate output folder. **A written run log**: what was read, how many rows, what was excluded and why, and the runtime — one line per run."),
        bp(18, "**وحدات صغيرة مستقلة**: قراءة، وبعدين تنظيف، وبعدين تحليل، وبعدين إخراج — أربع خطوات منفصلة يسهل اختبار كل واحدة فيها. **الفشل الواضح أحسن من النجاح الصامت**: لو بنية الملف مش متوقعة التنفيذ يوقف برسالة واضحة، بدل ما يطلع تقرير شكله صح وهو غلط.", "**Small independent modules**: read, clean, analyse, output — four separate steps each easy to test. **Explicit failure beats silent success**: on an unexpected file structure execution stops with a clear message instead of producing a report that looks right but is wrong."),
      ],
      levels: {
        simple: [
          L("what", "أربعة أسئلة «آه ولا لأ» قبل ما تبني أي أداة، وأربع قواعد أمان بعد ما تقرر تبني. تشبيه: قبل ما تشتري ماكينة للمصنع بتسأل: هنستخدمها كتير؟ المنتج ثابت؟ الغلط بالإيد مكلف؟ نقدر نفحص جودة إنتاجها؟", "Four yes/no questions before building any tool, and four safety rules once you decide to build. Like buying a machine for the plant: will we use it a lot? Is the product stable? Are manual mistakes costly? Can we check its output quality?"),
          L("why", "لأن بناء أداة لمهمة مش مناسبة بيضيّع وقت أكتر من اللي بيوفره، وأداة من غير قواعد أمان ممكن تمسح بيانات أو تطلع أرقام غلط من غير ما حد يحس.", "Because building a tool for the wrong task wastes more time than it saves, and a tool without safety rules may wipe data or silently produce wrong numbers."),
        ],
        mech: [
          L("how", "**الأسئلة الأربعة** بتحسب التكلفة مقابل العائد: التكرار والكلفة بيرفعوا العائد، والثبات وإمكانية التحقق بيقلّلوا مخاطرة البناء. **القواعد الأربع** بتحمي من أسوأ أخطاء الأتمتة: فقدان الأصل، وجهل إيه اللي حصل، والكود المتشابك، والغلط الصامت.", "**The four questions** weigh cost against benefit: frequency and error cost raise the benefit; stability and verifiability lower the build risk. **The four rules** guard against automation’s worst failures: losing originals, not knowing what happened, tangled code, and silent errors."),
          L("inside", "«الفشل الواضح أحسن من النجاح الصامت» أعمق فكرة هنا: أداة توقف وتقول «العمود (الكمية) مش موجود» تكلفك دقيقة. أداة تكمل وتملاه بصفر تكلفك قرار إداري مبني على رقم غلط.", "“Explicit failure beats silent success” is the deepest idea here: a tool that stops and says “column (quantity) not found” costs you a minute. One that carries on filling it with zero costs you a management decision built on a wrong number."),
          L("link", "دي نفس «القاعدتين اللي ماتتكسرش» في الماكرو ([[p10]]) بس مكبّرة، وهتلاقيها تاني في مبادئ تصميم الخادم ([[w4]]).", "These are the macro’s “two unbreakable rules” ([[p10]]) expanded, and you’ll meet them again in the server design principles ([[w4]])."),
        ],
        practice: [
          L("example", "**تقرير المبيعات الأسبوعي**: أسبوعي (تكرار ✓)، نفس الأعمدة كل أسبوع (ثبات ✓)، أخطاء النسخ بتوصل للمدير (كلفة ✓)، تقدر تقارنه بتقرير الأسبوع اللي فات بالإيد (تحقق ✓) ← يستاهل أداة.\n\n**خطة الحملة الإعلانية الجاية**: مرة في الربع، والقواعد بتتغير كل مرة ← أسرع بالإيد مع Prompt كويس.", "**Weekly sales report**: weekly (frequency ✓), same columns (stability ✓), copy errors reach the manager (cost ✓), comparable with last week’s manual report (verifiable ✓) → worth a tool.\n\n**Next ad campaign plan**: once a quarter, rules change each time → faster by hand with a good prompt."),
          L("apply", "حط مهمتك الحقيقية في [[worth|مختبر بوصلة القرار]] واعرف كام ساعة هتوفر سنويًا وإمتى هتسترد وقت البناء.", "Enter your real task in the [[worth|decision compass lab]] and see the hours saved per year and when the build pays back."),
        ],
        adv: [
          L("mistakes", "- **أتمتة مهمة لأنها مزعجة مش لأنها متكررة**.\n- **أداة من غير سجل**: يوم ما تغلط مش هتعرف ليه.\n- **إسكات الأخطاء** (try/except بيبلع كل الأخطاء) عشان الأداة «شكلها» مستقرة.", "- **Automating a task because it’s annoying, not because it recurs**.\n- **A tool with no log**: the day it fails you won’t know why.\n- **Silencing errors** (a catch-all that swallows everything) so the tool “looks” stable."),
          L("whennot", "مهمة مرة في السنة، أو قواعدها بتتغير كل مرة، أو مفيش طريقة تتأكد بيها من ناتجها — هتفضل أسرع بالإيد. الكتاب صريح: «أي مهمة مش بتحقق الشروط التلاتة هتفضل أسرع بالإيد».", "A once-a-year task, one whose rules change every time, or one whose output can’t be verified — stays faster by hand. The book is explicit: “any task that doesn’t meet the three conditions stays faster by hand.”"),
        ],
      },
      case: { field: { ar: "المخازن", en: "Warehouse" }, title: { ar: "نأتمت جرد آخر الشهر؟", en: "Should we automate month-end stocktaking?" },
        steps: {
          problem: { ar: "مطابقة كشف الجرد مع النظام بتاخد يومين كل شهر.", en: "Matching the stock count with the system takes two days a month." },
          old: { ar: "مقارنة بالإيد بند بند، وأخطاء نسخ بتظهر في المراجعة.", en: "Manual item-by-item comparison, with copy errors showing up in audits." },
          idea: { ar: "مرّر المهمة على بوصلة القرار قبل أي بناء.", en: "Run the task through the decision compass before building anything." },
          steps: { ar: "1. التكرار: شهري بس بياخد ساعات ✓.\n2. الثبات: نفس الأعمدة ونفس قاعدة الفرق المقبول ✓.\n3. الكلفة: فروق المخزون فلوس ✓.\n4. التحقق: نقارن بجرد الشهر اللي فات بالإيد ✓.\n5. البناء بالقواعد الأربع: نسخة، سجل، وحدات، توقف واضح.", en: "1. Frequency: monthly but takes hours ✓.\n2. Stability: same columns and same tolerance rule ✓.\n3. Cost: stock differences are money ✓.\n4. Verifiability: compare with last month’s manual count ✓.\n5. Build with the four rules: copy, log, modules, explicit stop." },
          result: { ar: "قرار مبني على معايير مش على الحماس، وأداة متوقع تختصر اليومين لساعات (يتقاس بعد أول تشغيل).", en: "A decision based on criteria rather than enthusiasm, and a tool expected to cut two days to hours (measured after the first run)." },
          risks: { ar: "لو شكل تصدير النظام اتغيّر فجأة لازم الأداة توقف برسالة واضحة، وأول شهر مطابقة كاملة بالإيد للتأكد.", en: "If the system export changes suddenly the tool must stop with a clear message, and the first month’s match stays fully manual to confirm." },
        } },
    },
    {
      id: "y3", unit: "u5", pages: [18, 19], diff: 2, min: 9, scene: "prefer", lab: "pipeline", related: ["y2", "y7", "s1"], pre: ["y2"],
      title: { ar: "إزاي تبني أتمتة تشتغل كل يوم بثبات ومن غير أعطال مفاجئة؟", en: "Level 1: run automation" },
      sum: { ar: "أتمتة بتنجح ١٠٠ مرة وتفشل في المرة ١٠١ من غير ما تقول أخطر من إنك تشتغل بإيدك. الأتمتة اللي يُعتمد عليها بتتأكد من كل خطوة، ولو حاجة فشلت بتوقف وتقول السبب.", en: "The tool map, the preference order that makes tools last for years, a typical chain, and essential run controls." },
      book: [
        bp(18, "تلات مستويات ورا بعض: **التشغيل** (الملفات وإكسل والمتصفح وبرامج ويندوز مع جدولة بتشيل التدخل بالإيد)، وبعدين **التحليل** (استعلام مباشر ومعالجة سريعة وفحص جودة)، وبعدين **العرض** (صفحة تفاعلية بتنقل القارئ من النتيجة للقرار).", "Three consecutive levels: **run** (files, Excel, browser and Windows apps, with scheduling that removes manual work), then **analysis** (direct queries, fast processing, quality checks), then **reporting** (an interactive page moving the reader from result to decision)."),
        bp(18, "خريطة الأدوات: **((playwright|Playwright))** بيتحكم في المتصفح · **((xlwings|xlwings))** بيتحكم في ملفات إكسل الحقيقية · **((pyautogui|PyAutoGUI))** بيحاكي الماوس ولوحة المفاتيح (أكتر حاجة ممكن تتكسر) · **((pywinauto|pywinauto))** بيتعامل مع برامج ويندوز من أزرارها الحقيقية · **((watchdog|watchdog))** بيبدأ التنفيذ لحظة ما ملف جديد يوصل · **جدولة ويندوز + ((pyinstaller|PyInstaller))** لتشغيل تلقائي وملف واحد يشتغل على أي جهاز.", "Tool map: **((playwright|Playwright))** drives the browser · **((xlwings|xlwings))** drives real Excel files · **((pyautogui|PyAutoGUI))** simulates mouse and keyboard (most fragile) · **((pywinauto|pywinauto))** handles Windows apps via their real buttons · **((watchdog|watchdog))** starts work the moment a new file arrives · **Windows Task Scheduler + ((pyinstaller|PyInstaller))** for automatic runs and one file that works on any PC."),
        bp(18, "ترتيب الأفضلية: **1. ملف أو API** (أثبت حاجة) ← **2. التحكم المباشر في البرنامج** (xlwings، Playwright) ← **3. عناصر واجهة البرنامج** (pywinauto) ← **4. محاكاة المستخدم** (آخر حل، ولازم تكتب في الكود ليه اضطريت له).", "Preference order: **1. file or API** (most stable) → **2. direct app control** (xlwings, Playwright) → **3. app UI elements** (pywinauto) → **4. user simulation** (last resort, with the reason written in the code)."),
        bp(18, "القاعدة الحاكمة: كل ما تختار مستوى أعلى، احتمال إن الأداة تتعطل مع أي تحديث للبرنامج أو للشاشة بيقل. **النزول لمستوى أقل لازم يكون قرار واعي، مش عادة سريعة.**", "The governing rule: the higher the level, the less likely the tool breaks on any app or screen update. **Going lower must be a conscious decision, not a quick habit.**"),
        bp(18, "سلسلة نموذجية من غير تدخل بالإيد: ملف جديد يوصل ← فحص البنية والأعمدة ← تنظيف وتوحيد ودمج ← حساب المؤشرات والشذوذ ← بناء التقرير وحفظه ← إشعار الناس بالرابط.", "A typical hands-off chain: a new file arrives → check structure and columns → clean, unify and merge → compute KPIs and anomalies → build and save the report → notify people with the link."),
        bp(18, "ضوابط التشغيل: **تشغيل تجريبي الأول** على نسخة ومقارنة بمخرج إيد معتمد · **حماية كلمات المرور** (ماتكتبهاش في الكود أبدًا) · **مهلة زمنية ومفتاح إيقاف** في أتمتة الواجهات · **توثيق في صفحة واحدة** يكفي لتسليم الأداة لأي زميل.", "Run controls: **a trial run first** on a copy, compared with an approved manual output · **protect passwords** (never written in the code) · **timeouts and a kill switch** in UI automation · **a one-page doc** enough to hand the tool to any colleague."),
        bp(19, "اتنين Prompts: **بناء أداة الأتمتة** (الخطوات والملفات والنتيجة، أثبت طريقة، ماتعدّلش الأصل، سجل، توقف واضح، خمس حالات اختبار)، و**المتابعة بعد أول تشغيل حقيقي** (السبب في قواعدي، ولا في بنية الملفات، ولا في الكود؟).", "Two prompts: **build the automation tool** (steps, files, result, most stable approach, no changes to originals, log, explicit stop, five tests), and **follow-up after the first real run** (is the cause my rules, the file structure, or the code?)."),
      ],
      levels: {
        simple: [
          L("what", "أدوات صغيرة ببايثون بتعمل اللي إنت بتعمله بالإيد على الكمبيوتر: تفتح ملفات، تنقل بيانات، تنزّل تقارير من مواقع، تضغط أزرار في برامج — وبعدين تشتغل لوحدها في موعد محدد أو لحظة ما ملف يوصل.", "Small Python tools that do what you do by hand on the PC: open files, move data, download reports from websites, press buttons in apps — then run on their own on schedule or when a file arrives."),
          L("why", "لأن الأتمتة الهشة بتتعطل مع أول تحديث للبرنامج وترجّعك للشغل اليدوي. ترتيب الأفضلية هو الفرق بين أداة تعيش سنين وأداة تموت في شهر.", "Because fragile automation breaks on the first app update and you’re back to manual work. The preference order is the difference between a tool that lives for years and one that dies in a month."),
        ],
        mech: [
          L("how", "اختار دايمًا أعلى مستوى ممكن:\n1. البيانات في ملف أو API؟ تعامل معاها مباشرة.\n2. لو لأ، تقدر تتحكم في البرنامج نفسه (إكسل، المتصفح)؟\n3. لو لأ، تقدر توصل لأزرار البرنامج الحقيقية؟\n4. بس لو كل ده فشل: حاكي الماوس — واكتب السبب في الكود.", "Always pick the highest possible level:\n1. Is the data in a file or available via an API? Use it directly.\n2. If not, can you control the app itself (Excel, browser)?\n3. If not, can you reach the app’s real buttons?\n4. Only if all fail: simulate the mouse — and note why in the code."),
          L("inside", "ليه المحاكاة هشة؟ لأنها معتمدة على **مكان** الزر على الشاشة: تغيّر دقة الشاشة، أو حجم النافذة، أو تصميم البرنامج، والأداة تضغط في المكان الغلط. pywinauto بيعرف الزر **باسمه** الحقيقي فبيفضل يشتغل.", "Why is simulation fragile? It depends on the button’s **position** on screen: change the resolution, window size or app design and the tool clicks the wrong spot. pywinauto knows the button **by its real name**, so it keeps working."),
          L("link", "قواعد [[y2]] الأربع بتظهر هنا كضوابط تشغيل، والسلسلة النموذجية هنا بتكبر وتبقى خط الأنابيب العشر خطوات في [[y7]]، وبعدين «النظام» في [[s1]].", "[[y2]]’s four rules appear here as run controls, and this typical chain grows into the ten-step pipeline in [[y7]], then the “system” in [[s1]]."),
        ],
        practice: [
          L("example", "**كل صباح** بتنزّل تقرير المبيعات من بوابة الشركة وتنسخه في إكسل. الأداة: Playwright بيسجّل الدخول وينزّل التقرير (المستوى 2)، وxlwings بيكتب في ملف إكسل جديد (المستوى 2)، وجدولة ويندوز بتشغّلها الساعة 8، وكلمة المرور في ملف إعدادات محمي مش في الكود.", "**Every morning** you download the sales report from the company portal and copy it into Excel. The tool: Playwright logs in and downloads (level 2), xlwings writes a new Excel file (level 2), Task Scheduler runs it at 8, and the password sits in a protected settings file, not the code."),
          L("apply", "شغّل [[pipeline|مختبر سلسلة الأتمتة]] بملف «عمود مفقود» مرتين: مرة مع التوقف الواضح ومرة من غيره. قارن النتيجتين.", "Run the [[pipeline|automation chain lab]] with the “missing column” file twice: once with explicit stop and once without. Compare."),
        ],
        adv: [
          L("mistakes", "- **تبدأ بـ PyAutoGUI لأنه أسهل** في الكتابة.\n- **كتابة كلمة المرور جوه الكود**.\n- **أتمتة واجهة من غير مهلة زمنية ومفتاح إيقاف**: الأداة تعلق أو تضغط من غير توقف.\n- **تعتمد على الأداة من غير تشغيل تجريبي** مقارن بمخرج بالإيد.", "- **Starting with PyAutoGUI because it’s easiest** to write.\n- **Writing the password in the code**.\n- **UI automation with no timeout or kill switch**: the tool hangs or clicks endlessly.\n- **Adopting the tool without a trial run** compared with a manual output."),
          L("whennot", "لو المهمة بتتنفّذ مرة في الشهر وبتاخد عشر دقائق، أو البرنامج شكله بيتغير طول الوقت ومش بيوفر ملف ولا API، الأتمتة ما تستاهلش التكلفة.", "If the task runs once a month and takes ten minutes, or the app keeps changing and offers no file or API, automation isn’t worth the cost."),
        ],
      },
    },
    {
      id: "y4", unit: "u1", pages: [19, 20], diff: 2, min: 9, scene: "drill7", lab: "quality", related: ["p6", "f3", "d2", "y3"], pre: ["f8"],
      title: { ar: "ليه لازم نفحص البيانات قبل ما نحللها؟", en: "Level 2: the analysis engine — quality first" },
      sum: { ar: "لو البيانات فيها تكرار أو تواريخ ناقصة أو وحدات مختلفة، أي تحليل مبني عليها هيطلع غلط مهما كان شكله مقنع. فحص البيانات بييجي قبل أي حساب.", en: "DuckDB, Polars and ydata-profiling, why quality checks are mandatory, the seven questions before any chart, and breaking down “efficiency fell 7%”." },
      book: [
        bp(19, "تلات أدوات بتكفي أغلب الحالات على جهاز واحد: **((duckdb|DuckDB))** لاستعلام SQL مباشر على ملفات إكسل أو ملفات نصية أو حتى مجلد كامل مرة واحدة · **((polars|Polars))** لمعالجة الجداول الكبيرة بسرعة عالية جدًا حتى لو حجمها أكبر من الذاكرة · **((profiling|ydata-profiling))** بيطلع تقرير فوري عن أي ملف جديد: القيم الناقصة والتكرارات والأرقام الشاذة والعلاقات.", "Three tools cover most cases on one machine: **((duckdb|DuckDB))** for direct SQL queries on Excel or text files, even a whole folder at once · **((polars|Polars))** for very fast processing of big tables, even beyond memory · **((profiling|ydata-profiling))** produces an instant report on any new file: missing values, duplicates, outliers and relationships."),
        bp(19, "**ليه الجودة الأول؟** نتيجة دقيقة على بيانات معيبة بتدي قرار غلط بثقة عالية جدًا. فحص الجودة خطوة أولى لازمة، مش خطوة اختيارية تسيبها لآخر الوقت.", "**Why quality first?** A precise result on broken data gives a wrong decision with very high confidence. The quality check is a mandatory first step, not an optional one left for the end."),
        bp(19, "سبعة أسئلة قبل أي رسم: إيه اللي حصل؟ ← فين؟ ← ليه؟ ← إيه العوامل المؤثرة؟ ← حادثة ولا متكرر؟ ← أثره الكمي والمالي؟ ← لو استمر إيه اللي هيحصل؟ ⟵ **إيه القرار المطلوب؟** الرسم نتيجة للأسئلة دي مش بديل عنها.", "Seven questions before any chart: what happened? → where? → why? → which factors? → one-off or recurring? → quantitative and financial impact? → what if it continues? ⟵ **what decision is needed?** The chart is a result of these questions, not a substitute."),
        bp(19, "لما التقرير يقول «الكفاءة انخفضت 7%»: أي موديل اتأثر؟ إيه التوقفات وأسبابها؟ أي خط أو فرع؟ الكمية كانت أقل من الطبيعي؟ أي وردية؟ كان فيه نقص في الخامات؟ من إمتى؟ حصلت قبل كده؟ تغيير الموديل أخد قد إيه؟ الأثر المالي الفعلي إيه؟", "When a report says “efficiency fell 7%”: which model? What stoppages and causes? Which line or branch? Was output below normal? Which shift? Were materials short? Since when? Has it happened before? How long did the model changeover take? What’s the real financial impact?"),
        bp(19, "Prompt التحليل المنضبط: ماتبدأش برسم أي حاجة — افحص الجودة، وبعدين حدد الأسئلة اللي البيانات فعلًا تسمح بيها، وبعدين حلّل، واختم بخمس استنتاجات وتلات إجراءات مع دليل رقمي لكل استنتاج، وقائمة باللي ما تقدرش تجزم بيه.", "The disciplined-analysis prompt: don’t draw anything — check quality, then decide which questions the data really allows, then analyse, ending with five conclusions and three actions with numeric evidence for each, and a list of what can’t be concluded."),
        bp(20, "Prompt فحص الجودة بلغة بسيطة: كام صف؟ قيم ناقصة في أي أعمدة؟ صفوف مكررة؟ أرقام غريبة برة النطاق؟ البيانات مغطية الفترة كاملة من غير فجوات؟ وبعدين المشاكل بترتيب الأهمية مع إصلاح بسيط لكل مشكلة.", "The plain-language quality prompt: how many rows? Missing values and in which columns? Duplicate rows? Strange out-of-range numbers? Does the data cover the whole period with no gaps? Then problems by importance with a simple fix for each."),
      ],
      levels: {
        simple: [
          L("what", "قبل ما تحلّل أي ملف، **افحصه** زي ما الدكتور بيفحص التحاليل قبل التشخيص: فيه خانات فاضية؟ تكرار؟ رقم غريب جدًا؟ أيام ناقصة؟ بعدها بس تسأل الأسئلة السبعة، وبعدها بس ترسم.", "Before analysing any file, **check it** the way a doctor checks lab results before diagnosing: blanks? duplicates? a very strange number? missing days? Only then ask the seven questions, and only then draw."),
          L("why", "لأن رقم واحد غلط (صفر زيادة، أو صف مكرر) بيغيّر المتوسط وبيغيّر القرار. والأخطر إن النتيجة شكلها دقيقة جدًا فمحدش بيشك فيها.", "Because one wrong number (an extra zero, a duplicate row) changes the average and the decision. Worse, the result looks very precise, so nobody doubts it."),
        ],
        mech: [
          L("how", "**الترتيب اللازم**: جودة ← أسئلة ← تحليل ← رسم ← قرار.\n- الجودة: ydata-profiling أو Prompt الجودة.\n- الأسئلة: السبعة، مع تفكيك الرقم العام لأسئلة فرعية.\n- التحليل: DuckDB للاستعلام، وPolars للملفات الكبيرة.", "**The mandatory order**: quality → questions → analysis → chart → decision.\n- Quality: ydata-profiling or the quality prompt.\n- Questions: the seven, breaking the headline number into sub-questions.\n- Analysis: DuckDB for queries, Polars for big files."),
          L("inside", "ليه التفكيك بيحوّل رقم لقرار؟ لأن «الكفاءة −7%» مالهاش مسؤول. «خط 2، الوردية الليلية، توقفات تغيير الموديل من أسبوعين» لها مسؤول وتقدر تتعامل معاها.", "Why does breakdown turn a number into a decision? Because “efficiency −7%” has no owner. “Line 2, night shift, model-changeover stoppages for two weeks” has an owner and can be fixed."),
          L("link", "ده امتداد لـ Prompt «تفكيك مشكلة» ([[p6]]) ولقاعدة «جودة البيانات والـ Context» ([[f3]])، ونفس المبدأ بيرجع كمرحلة «التحقق» في لوحة المعلومات ([[d2]]).", "This extends the “break down a problem” prompt ([[p6]]) and the “data and context quality” rule ([[f3]]); the same principle returns as the “verify” stage in dashboards ([[d2]])."),
        ],
        practice: [
          L("example", "في [[quality|مختبر الجودة]]: بيانات إنتاج يومية فيها صف مكرر، وقيمة 9800 بدل 980، وخانة فاضية، ويوم ناقص. المتوسط «شكله منطقي»، بس بعد الفحص والاستبعاد الرقم بيتغيّر — وبيظهر إن خط B هو المشكلة بسبب توقفات طويلة بتزيد.", "In the [[quality|quality lab]]: daily production data with a duplicate row, 9800 instead of 980, a blank and a missing day. The average “looks reasonable”, but after checking and excluding, the number changes — and line B emerges as the problem, with long, rising stoppages."),
          L("apply", "خد ملف بيانات صغير حقيقي من شغلك، واطلب Prompt فحص الجودة قبل أي تحليل. اكتب أهم مشكلتين ظهرت.", "Take a small real data file from work and run the quality prompt before any analysis. Write down the top two problems it found."),
        ],
        adv: [
          L("mistakes", "- **تبدأ بالرسم**: لوحة مزدحمة ما بتغيّرش ولا قرار.\n- **حذف القيم الشاذة أوتوماتيك**: الرقم الشاذ ممكن يكون الحدث المهم نفسه — افحصه قبل الحذف.\n- **استنتاجات من غير دليل رقمي**.", "- **Starting with charts**: a crowded board that changes no decision.\n- **Auto-deleting outliers**: the outlier may be the important event itself — check it first.\n- **Conclusions without numeric evidence**."),
          L("whennot", "ماتستخدمش الأدوات الثقيلة لملف صغير يكفيه إكسل و Prompt جودة. ولما تحتاج صلاحيات ومقاييس موحدة لعشرات المستخدمين، انتقل للمنصة المؤسسية ([[y5]]).", "Don’t use heavy tools for a small file that Excel and a quality prompt can handle. When you need permissions and unified metrics for dozens of users, move to an enterprise platform ([[y5]])."),
        ],
      },
      case: { field: { ar: "التصنيع", en: "Manufacturing" }, title: { ar: "«الكفاءة انخفضت 7%» — من رقم لسبب", en: "“Efficiency fell 7%” — from a number to a cause" },
        steps: {
          problem: { ar: "التقرير الشهري بيقول الكفاءة انخفضت 7%، والإدارة عايزة خطة خلال أسبوع.", en: "The monthly report says efficiency fell 7%, and management wants a plan within a week." },
          old: { ar: "اجتماع طويل وتخمينات: «الصيانة»، «العمالة الجديدة»، «الخامات».", en: "A long meeting and guesses: “maintenance”, “new workers”, “materials”." },
          idea: { ar: "فحص الجودة الأول، وبعدين الأسئلة السبعة والأسئلة الفرعية من الكتاب.", en: "Quality check first, then the seven questions and the book’s sub-questions." },
          steps: { ar: "1. فحص الجودة: اتكتشف أيام مكررة في بيانات خط 3.\n2. بعد التنظيف: الانخفاض الحقيقي في خط 2 بس.\n3. أي وردية؟ الليلية.\n4. ليه؟ توقفات تغيير الموديل اتضاعفت من أسبوعين.\n5. الأثر المالي ولو استمر إيه اللي هيحصل.", en: "1. Quality check: duplicated days found in line 3 data.\n2. After cleaning: the real drop is only on line 2.\n3. Which shift? Night.\n4. Why? Model-changeover stoppages doubled two weeks ago.\n5. Financial impact and what if it continues." },
          result: { ar: "قرار محدد: مراجعة إجراء تغيير الموديل في الوردية الليلية لخط 2 خلال أسبوع، بمسؤول وموعد (أرقام القصة افتراضية).", en: "A specific decision: review line 2’s night-shift changeover procedure within a week, with an owner and a date (story numbers are hypothetical)." },
          risks: { ar: "لو البيانات فضلت ناقصة (فجوات أيام) اذكرها كقيد واضح في التقرير بدل استنتاج مش مدعوم.", en: "If data remains incomplete (missing days), state it as an explicit limit in the report instead of a conclusion it doesn’t support." },
        } },
    },
    {
      id: "y5", unit: "u4", pages: [20, 21], diff: 3, min: 7, related: ["y4", "y6", "s1"], pre: ["y4"],
      title: { ar: "بايثون ولا منصة كبيرة للشركة؟", en: "Python or an enterprise reporting platform?" },
      sum: { ar: "أداة صغيرة تكفي لتقرير بيشوفه ٣ أشخاص. لكن لما يبقى عندك مئات المستخدمين وصلاحيات ومراجعات، هتحتاج منصة. اللي بيحدد الاختيار حجم المسؤولية، مش شهرة الأداة.", en: "The question isn’t which is stronger but which fits your scale and governance: when Python is enough, when a platform is needed, and four signals to switch." },
      book: [
        bp(20, "السؤال مش مين أقوى، لكن **مين يطابق حجم الاستخدام ومتطلبات الحوكمة** في شركتك فعلًا.", "The question isn’t which is stronger but **which matches your actual scale of use and governance needs**."),
        bp(20, "حل بايثون بيكفي لما: النطاق محدود (إدارة أو موقع أو فريق صغير)، والمنطق خاص بالشركة (قواعد داخلية، تنبؤ، سيناريوهات القوالب الجاهزة ما بتدعمهاش)، والتوزيع بسيط (ملف أو صفحة لعدد محدود)، والسلسلة متكاملة في أداة واحدة.", "Python suffices when: the scope is limited (one department, site or small team), the logic is company-specific (internal rules, forecasting, scenarios templates don’t support), distribution is simple (a file or page for a few people), and the chain is integrated in one tool."),
        bp(20, "المنصة المؤسسية بتبقى لازمة لما: مستخدمين كتير بصلاحيات مختلفة، ومقاييس موحدة في الشركة كلها، وحوكمة مركزية (تحديث مجدول ومراقبة من قسم تقني)، وأصل مؤسسي طويل المدى يفضل شغال بعد ما صاحبه ينقل.", "An enterprise platform is needed when: many users with different permissions, unified metrics across the company, central governance (scheduled refresh and monitoring by IT), and a long-term asset that keeps working after its owner moves on."),
        bp(20, "مقارنة: سرعة أول نتيجة (ساعات لأيام ↔ أيام لأسابيع)، حرية منطق التحليل (كاملة ↔ محدودة بالمنتج)، الصلاحيات والحوكمة (تتبني بالإيد ↔ مدمجة مركزيًا)، كلفة الاستمرار (صيانة كود ومعرفة شخص واحد ↔ تراخيص سنوية وإدارة منصة).", "Comparison: time to first result (hours–days ↔ days–weeks), analysis freedom (full ↔ limited by the product), permissions and governance (built by hand ↔ built-in, central), running cost (code upkeep and individual knowledge ↔ annual licences and platform management)."),
        bp(20, "الخلاصة المهنية: الحلّين مش منافسين. **ابني الحل الأخف الأول** عشان تجاوب على السؤال اللي قدامك، ولو التقرير فعلًا بقى أصل كتير بيستخدمه ومحتاج صلاحيات ومقاييس موحدة، انتقل للمنصة **بمعرفة اكتسبتها من النموذج الأول مش بافتراضات نظرية**.", "The professional conclusion: the two aren’t rivals. **Build the lighter solution first** to answer the question at hand; if the report truly becomes an asset many use, needing permissions and unified metrics, move to the platform **with knowledge gained from the first model, not theoretical assumptions**."),
        bp(20, "أربع إشارات للانتقال: نسخ كتير بأرقام مختلفة بين الإدارات · طلبات صلاحيات متكررة («القسم ده مينفعش يشوف بيانات القسم التاني») · اعتماد كبير على شخص واحد بيشغّل الملف من جهازه · تضارب في المقاييس بين تقارير من مصادر مختلفة.", "Four signals to switch: multiple copies with different numbers across departments · repeated permission requests (“this department mustn’t see that one’s data”) · dependence on one person running the file from their PC · metrics that don’t match across multi-source reports."),
        bp(21, "Prompt خطة الترقية للمنصة: انتقال تدريجي يحافظ على منطق التحليل في بايثون **كمرجع للتحقق من الأرقام** في المنصة الجديدة، وأي تقرير ينقل الأول، والمخاطر، وإزاي تتجنب فقدان البيانات أو منطق الحساب.", "The platform-upgrade prompt: a gradual move that keeps the Python logic **as a reference to verify numbers** in the new platform, which report moves first, the risks, and how to avoid losing data or calculation logic."),
      ],
      levels: {
        simple: [
          L("what", "قرار بين طريقين: **سكربت بايثون** تبنيه بنفسك بسرعة لفريق صغير، أو **منصة تقارير** مؤسسية لكل الشركة بصلاحيات وتحديث مركزي. زي ملف إكسل بيستخدمه قسم واحد مقابل نظام مركزي للشركة كلها: لكل واحد حجم شغل يناسبه.", "A choice between two paths: a **Python script** you build quickly for a small team, or an enterprise **reporting platform** for the whole company with permissions and central refresh. Like a spreadsheet one department uses versus a central system for the whole company — each suits a different scale of work."),
          L("why", "لأن الغلط مكلف في الاتجاهين: منصة كاملة لسؤال بسيط بتضيّع أسابيع، وسكربت على جهاز موظف واحد والإدارة كلها معتمدة عليه خطر لما يغيب.", "Because the mistake is costly both ways: a full platform for a simple question wastes weeks, and a script on one person’s PC that all management depends on is a risk when they’re away."),
        ],
        mech: [
          L("how", "القاعدة: **ابدأ خفيف، وراقب الإشارات الأربع**. لما واحدة تظهر (نسخ كتير بأرقام مختلفة، طلبات صلاحيات، شخص واحد حرج، مقاييس متضاربة) ده علامة إن التقرير بقى أصل مؤسسي يستاهل منصة.", "The rule: **start light and watch the four signals**. When one appears (multiple copies with different numbers, permission requests, one critical person, conflicting metrics), the report has become a company asset worth a platform."),
          L("inside", "ليه نحتفظ بمنطق بايثون بعد الانتقال؟ لأنه **مرجع للتحقق**: نفس البيانات لازم تطلع نفس الأرقام في المنصة الجديدة. أي فرق بيكشف غلط في النقل قبل ما يوصل للإدارة.", "Why keep the Python logic after switching? It’s a **verification reference**: the same data must give the same numbers on the new platform. Any difference exposes a migration error before it reaches management."),
          L("link", "الإشارة الرابعة «تضارب المقاييس» هي نفس مبدأ «مصدر حقيقة واحد» في بناء الأنظمة ([[s1]]).", "The fourth signal, “conflicting metrics”, is the “single source of truth” principle in building systems ([[s1]])."),
        ],
        practice: [
          L("example", "تقرير جودة بدأ بسكربت لقسم واحد. بعد سنة بقى يتبعت لست إدارات، وكل إدارة بتعدّله وأرقام مختلفة بتظهر في الاجتماعات، والمهندس اللي بناه بينقل لموقع تاني. تلات إشارات ظهرت ← وقت الانتقال لمنصة مع الاحتفاظ بالسكربت كمرجع.", "A quality report started as a script for one department. A year later it goes to six departments, each edits it so meetings show different numbers, and the engineer who built it is moving site. Three signals → time to move to a platform, keeping the script as a reference."),
          L("apply", "قارن بين الخيارين على تقرير حقيقي في [[compare|محرك المقارنات]] (مجموعة «طريقة البناء»)، وراجع: أي من الإشارات الأربع شايفها في تقاريرك دلوقتي؟", "Compare the two options on a real report in the [[compare|comparison engine]] (“build approach” family), and check: which of the four signals do you see in your reports today?"),
        ],
        adv: [
          L("mistakes", "- **شراء منصة قبل ما تعرف السؤال**: «هنبني لوحة لكل حاجة».\n- **الاستمرار على السكربت رغم الإشارات**: أرقام متضاربة في كل اجتماع.\n- **الانتقال دفعة واحدة** من غير مرجع للتحقق.", "- **Buying a platform before knowing the question**: “a dashboard for everything”.\n- **Staying on the script despite the signals**: conflicting numbers every meeting.\n- **Migrating all at once** with no verification reference."),
          L("whennot", "قرار المنصة غالبًا مش قرارك لوحدك (تراخيص، قسم تقني، سياسات)؛ دورك إنك تقدّم نموذج شغال ومعرفة اكتسبتها تخلي القرار أسهل وأقل مخاطرة.", "The platform decision usually isn’t yours alone (licences, IT, policies); your role is to bring a working model and gained knowledge that make the decision easier and less risky."),
        ],
      },
    },
    {
      id: "y6", unit: "u4", pages: [21, 22], diff: 2, min: 8, scene: "stations", related: ["p11", "d2", "w3"], pre: ["y4"],
      title: { ar: "إزاي تخلي المدير يفهم التقرير في دقيقة؟", en: "Level 3: from analysis to an interactive executive experience" },
      sum: { ar: "المدير عايز يعرف في دقيقة: المشكلة فين، وحجمها قد إيه، والمطلوب إيه. التقرير لازم يجاوب الأسئلة دي بالترتيب ده، والتفاصيل تيجي بعدها.", en: "One page that opens in a click and leads its reader from result to decision in minutes: seven stations, the 30-second test, six mistakes." },
      book: [
        bp(21, "الهدف مش تجميل الأرقام، لكن **تبني صفحة واحدة تتفتح بضغطة، وتقود اللي بيقراها من النتيجة للقرار في دقائق**.", "The goal isn’t prettifying numbers but **building one page that opens in a click and leads its reader from result to decision in minutes**."),
        bp(21, "طريقتين: **مخرج مستقل** — ((plotly|Plotly)) بيوفر أكتر من أربعين نوع رسم تفاعلي وبيحفظهم كصفحة ويب واحدة تشتغل من غير نت ومن غير تثبيت. **تطبيق تحليلي كامل** — ((streamlit|Streamlit)) بيبني تطبيق بأسطر قليلة للنماذج السريعة، و((dash|Dash)) أنسب لما المشروع يبقى أداة دائمة بتحكم أدق.", "Two ways: **a standalone output** — ((plotly|Plotly)) offers 40+ interactive chart types and saves them as one web page that works offline with no install. **A full analytics app** — ((streamlit|Streamlit)) builds an app in a few lines for quick prototypes; ((dash|Dash)) suits a permanent tool with finer control."),
        bp(21, "المسار الموصى بيه: نموذج سريع بـ Streamlit تتأكد من الفكرة الأول، وبعدين تنتقل لـ Dash بس بعد ما المتطلبات تثبت ومش بتتغير كتير.", "Recommended path: a quick Streamlit prototype to validate the idea first, then move to Dash only once requirements settle."),
        bp(21, "سبع محطات بدل صفحة مزدحمة بالرسوم: **إيه اللي حصل؟** (رقم واحد كبير) · **كويس ولا وحش؟** (مقارنة بالخطة والفترة اللي فاتت والهدف) · **المشكلة فين؟** (رسم تفاعلي واحد) · **ليه حصلت؟** (الأسباب مرتبة) · **التركيز فين؟** (أعلى تلات مناطق بس) · **لو استمر إيه اللي هيحصل؟** (توقع بسيط) · **نعمل إيه دلوقتي؟** (تلات قرارات بمسؤول وموعد).", "Seven stations, not a wall of charts: **what happened?** (one big number) · **good or bad?** (vs plan, prior period, target) · **where is the problem?** (one interactive chart) · **why?** (causes ranked) · **where to focus?** (top three areas only) · **what if it continues?** (a simple forecast) · **what now?** (three decisions with owner and date)."),
        bp(21, "معيار النجاح الوحيد: **الرسالة الأساسية تتفهم في أول تلاتين ثانية من فتح الصفحة**، وبعدين التعمق لمن عايزه بس.", "The only success test: **the core message is understood within the first thirty seconds**, with deeper detail left for those who want it."),
        bp(21, "طبقة تحسين اختيارية: ((jinja|Jinja)) لقوالب شكلها ثابت، و((gsap|GSAP)) لحركة موجّهة (المشكلة الأول، وبعدين الرسم، وبعدين السبب، وبعدين الحل)، و((revealjs|Reveal.js)) لتحويل الصفحة لعرض شرائح. **الحركة وسيلة توجّه الانتباه مش زينة؛ أي حركة مش بتسهّل فهم الفكرة الجاية تتشال فورًا.**", "An optional polish layer: ((jinja|Jinja)) for fixed-look templates, ((gsap|GSAP)) for guided motion (problem, then chart, then cause, then fix), and ((revealjs|Reveal.js)) to turn the page into slides. **Motion guides attention, it isn’t decoration; any motion that doesn’t ease the next idea is cut at once.**"),
        bp(21, "ستة أخطاء بتفسد الصفحة: رسوم من غير قرار · أرقام من غير مرجع · فلاتر محدش بيستخدمها · ألوان من غير معنى (نفس اللون يعني حاجة مختلفة) · حركة قبل الأولوية · تفاصيل قبل الرسالة.", "Six mistakes: charts with no decision · numbers with no reference · unused filters · meaningless colours (the same colour meaning different things) · motion before priority · details before the message."),
        bp(22, "اتنين Prompts: **الصفحة التنفيذية** (تسلسل من النتيجة للقرار، مؤشرات قليلة، فلاتر مفيدة بس، تشتغل محلي من غير نت)، و**صياغة المحطات السبع نصًا الأول** قبل ما تبني أي رسم.", "Two prompts: **the executive page** (a sequence from result to decision, few KPIs, only useful filters, works locally offline), and **write the seven stations as text first** before building any chart."),
      ],
      levels: {
        simple: [
          L("what", "صفحة واحدة المدير يفتحها بضغطة، يشوف رقم واحد كبير، وبعدين كويس ولا وحش، وبعدين المشكلة فين وليه، وبعدين تلات قرارات مطلوبة. تشبيه: زي نشرة أخبار كويسة — العنوان الأول، وبعدين التفاصيل لمن عايز.", "One page a manager opens in a click: one big number, then whether it’s good or bad, then where the problem is and why, then three decisions needed. Like a good news bulletin — headline first, details for those who want them."),
          L("why", "لأن المدير ماعندوش وقت لصفحة مزدحمة بالرسوم. لو مش هيفهم الرسالة في تلاتين ثانية، مش هيتخذ قرار.", "Because a manager has no time for a wall of charts. If they don’t get the message in thirty seconds, they won’t make the decision."),
        ],
        mech: [
          L("how", "اكتب المحطات السبع **نصًا** الأول (Prompt الصياغة)، وبعدين اختار لكل محطة عنصر واحد: رقم كبير، مقارنة، رسم تفاعلي، قائمة أسباب، تلات مناطق، توقع، تلات قرارات. وبعدين ابني الصفحة (Plotly لملف مستقل، أو Streamlit لنموذج سريع).", "Write the seven stations as **text** first (the wording prompt), then pick one element per station: a big number, a comparison, an interactive chart, a list of causes, three areas, a forecast, three decisions. Then build the page (Plotly for a standalone file, Streamlit for a quick prototype)."),
          L("inside", "قاعدة الحركة: الحركة الكويسة **بتكشف الأفكار بترتيب الفهم** (المشكلة وبعدين الرسم وبعدين السبب وبعدين الحل). الأكاديمية نفسها بتطبّق القاعدة في مشاهدها: كل حركة بتحكي خطوة.", "The motion rule: good motion **reveals ideas in the order of understanding** (problem, chart, cause, fix). This academy applies the same rule in its scenes: every motion explains a step."),
          L("link", "المحطات السبع هي القصة الإدارية في [[p11]] بصيغة صفحة تفاعلية، والأسئلة السبعة في [[y4]] بصيغة عرض. هتبنيها بنفسك في لوحة المعلومات ([[d2]]) وتطبيق الويب ([[w3]]).", "The seven stations are [[p11]]’s management story as an interactive page, and [[y4]]’s seven questions as a presentation. You’ll build them yourself in the dashboard ([[d2]]) and the web app ([[w3]])."),
        ],
        practice: [
          L("example", "تقرير مبيعات شهري: (1) «المبيعات 1.28 مليون» (2) «أقل من الخطة بـ6%» (3) رسم تفاعلي للفروع (4) «السبب: الجيزة −18% بسبب نقص منتج» (5) «تلات منتجات في فرعين» (6) «لو استمر: −400 ألف في الربع» (7) «تلات قرارات بمسؤول وموعد» — أرقام افتراضية للتوضيح.", "A monthly sales report: (1) “Sales 1.28M” (2) “6% below plan” (3) an interactive branch chart (4) “Cause: Giza −18% due to a stock-out” (5) “three products in two branches” (6) “if it continues: −400k this quarter” (7) “three decisions with owner and date” — hypothetical numbers."),
          L("apply", "خد آخر تقرير بعته واكتب محطاته السبع نصًا في خمسة أسطر. أي محطة كانت ناقصة؟ (غالبًا: «نعمل إيه دلوقتي؟»).", "Take the last report you sent and write its seven stations as text in five lines. Which station was missing? (Usually “what now?”.)"),
        ],
        adv: [
          L("mistakes", "- **الحركة قبل الرقم**: الرسم بيتحرك قبل ما المستخدم يقرأ الرقم الأساسي.\n- **فلاتر كتير** الجمهور مش بيستخدمها.\n- **أحمر يعني «وحش» في رسم و«القاهرة» في رسم تاني**.", "- **Motion before the number**: the chart moves before the user reads the key number.\n- **Many filters** the audience never uses.\n- **Red means “bad” in one chart and “Cairo” in another**."),
          L("whennot", "لوحة تشغيل يومية لفريق المصنع مختلفة جذريًا عن صفحة الإدارة العليا: الأولى تفاصيل ومتابعة لحظية، والتانية رسالة وقرار. ماتستخدمش قالب الإدارة للتشغيل.", "A daily operational board for the plant team differs radically from a top-management page: the first is detail and live tracking, the second is message and decision. Don’t use the executive template for operations."),
        ],
      },
      case: { field: { ar: "المبيعات", en: "Sales" }, title: { ar: "من ملف إكسل 12 ورقة لصفحة تتفهم في 30 ثانية", en: "From a 12-sheet Excel file to a page understood in 30 seconds" },
        steps: {
          problem: { ar: "التقرير الشهري للمدير ملف إكسل من 12 ورقة، والمدير كل شهر بيسأل نفس السؤال: «يعني إيه؟».", en: "The manager’s monthly report is a 12-sheet Excel file, and every month he asks the same question: “so what?”." },
          old: { ar: "إرسال الملف زي ما هو مع بريد طويل بيشرح الأرقام.", en: "Send the file as is with a long email explaining the numbers." },
          idea: { ar: "صفحة واحدة بالمحطات السبع، تتبني نصًا الأول وبعدين تفاعلي.", en: "One page with the seven stations, built as text first, then interactive." },
          steps: { ar: "1. Prompt صياغة المحطات السبع نصًا.\n2. مراجعة النص مع المدير مرة واحدة.\n3. Prompt الصفحة التنفيذية (Plotly، ملف واحد).\n4. اختبار التلاتين ثانية مع زميل مش شايف البيانات.", en: "1. The seven-stations text prompt.\n2. Review the text with the manager once.\n3. The executive-page prompt (Plotly, one file).\n4. The 30-second test with a colleague who hasn’t seen the data." },
          result: { ar: "صفحة تتبعت بالبريد وتتفتح بنقرة، وتنتهي بتلات قرارات.", en: "A page sent by email and opened in a click, ending with three decisions." },
          risks: { ar: "كل رقم في الصفحة لازم يطابق المصدر؛ والتوقع («لو استمر») يتعرض كتقدير مش كحقيقة.", en: "Every number on the page must match the source; the forecast (“what if it continues”) is shown as an estimate, not a fact." },
        } },
    },
    {
      id: "y7", unit: "u5", pages: [22, 23], diff: 3, min: 8, scene: "pipeline10", related: ["y3", "w5", "s2"], pre: ["y6"],
      title: { ar: "من ٤ ملفات خام لتقرير يفتح بضغطة واحدة", en: "The reference project: from raw files to a one-click report" },
      sum: { ar: "ملفات بتتنزل وتتنضف وتتجمع كل أسبوع بإيد موظفين ممكن تتحول لسلسلة واحدة بتشتغل بضغطة، وفيها فحص عند كل خطوة بيوقفها لو فيه حاجة غلط.", en: "A ten-step pipeline joining the three levels, acceptance criteria, a delivery checklist, and the decision and learning map." },
      book: [
        bp(22, "مشروع واحد بيجمع الأتمتة والتحليل والعرض في نظام متكامل يشتغل لوحده، من غير تدخل بالإيد بعد الإعداد الأول.", "One project joining automation, analysis and reporting into a self-running system, with no manual work after setup."),
        bp(22, "خط الأنابيب الكامل — عشر خطوات: مراقبة المجلد ← قراءة أوتوماتيك ← تنظيف ودمج ← فحص الجودة ← محرك التحليل ← اكتشاف المشاكل ← حساب المؤشرات ← بناء الرسوم ← صفحة تفاعلية ← ملف واحد يتبعت.", "The full pipeline — ten steps: watch the folder → auto-read → clean and merge → quality check → analysis engine → detect problems → compute KPIs → build charts → interactive page → one file sent."),
        bp(22, "معايير القبول: **تشغيل واحد متكامل** من غير تدخل بالإيد في النص · **سلامة البيانات الأصلية** بعد كل تشغيل · **سجل تشغيل واضح** (إيه اللي اتقرا وإيه اللي اتستبعد وليه) · **ينتهي بقرار مش بملخص**.", "Acceptance criteria: **one integrated run** with no manual step in between · **original data intact** after every run · **a clear run log** (what was read, what was excluded and why) · **ends with a decision, not a summary**."),
        bp(22, "قائمة تحقق قبل التسليم: اختبار كامل على بيانات شهر حقيقي ومقارنة النتيجة رقم برقم بالمخرج بالإيد المعتمد · سلوك معروف من قبل لملف ناقص أو عمود مفقود أو صف تالف · مسار مجرب لاسترجاع النسخة اللي فاتت من التقرير · صفحة توثيق واحدة تكفي تسلّم الأداة · كل رقم ظاهر ليه مصدر تقدر تتتبعه · زمن تنفيذ معروف ومقبول.", "Pre-delivery checklist: a full test on a real month, compared number by number with the approved manual output · known behaviour for a missing file, column or corrupt row · a tested path to restore the previous report · a one-page doc enough to hand over the tool · every number traceable to a source · a known, acceptable runtime."),
        bp(23, "تبدأ من أي مستوى؟ **التشغيل** لمن بينفّذ مهمة بالإيد متكررة دلوقتي (نسخ بيانات من نظام لإكسل كل صباح) · **التحليل** لمن عنده بيانات بس مش فاهم ليه مؤشر اتغيّر (ليه كفاءة خط نزلت) · **العرض** لمن بيقدّم نتيجة للإدارة بشكل دوري (تقرير أسبوعي لمدير القسم).", "Which level to start with? **Run** if you do a recurring manual task now (copying system data to Excel every morning) · **analysis** if you have data but don’t know why an indicator changed (why a line’s efficiency fell) · **reporting** if you present results to management regularly (a weekly report to the department head)."),
        bp(23, "خارطة تعلّم لمن يبدأ من الصفر: أداة صغيرة الأول ← فحص جودة حقيقي ← الأسئلة قبل الرسم ← صفحة واحدة تشاركها مع زميل واحد ← المنصة بس لما تحتاج.", "A learning map from zero: a small tool first → a real quality check → questions before charts → one page shared with one colleague → a platform only when needed."),
        bp(23, "الخلاصة: الأتمتة تبدأ من أصغر مهمة متكررة، والتحليل من فحص الجودة مش من الرسم الأول، والعرض بينجح لما ينتهي بقرار. **ماتنتقلش لمستوى جديد قبل ما اللي قبله يشتغل بثبات ومن غير أخطاء صامتة** — ده الفرق بين أداة تصمد سنين وأداة تتبني وتتهمل بعد أول شهر.", "Conclusion: automation starts with the smallest recurring task, analysis with a quality check not the first chart, and reporting succeeds when it ends with a decision. **Don’t move up a level until the previous one runs reliably with no silent errors** — the difference between a tool that lasts years and one abandoned after a month."),
      ],
      levels: {
        simple: [
          L("what", "المشروع اللي بيجمع كل الدليل: ملف يوصل لمجلد ← الأداة بتقراه وتنظفه وتفحصه وتحلله وتبني صفحة ← وبتبعته — وكل ده من غير ما تلمس حاجة. تشبيه: خط إنتاج في مصنع، بس للمعلومات.", "The project that pulls the guide together: a file lands in a folder → the tool reads, cleans, checks and analyses it, builds a page → and sends it — all without you touching anything. Like a factory production line, for information."),
          L("why", "لأن الأدوات المنفصلة بتوفر دقائق، أما السلسلة الكاملة بتشيل المهمة من يومك. والمعايير بتضمن إنها تشتغل بأمان: ماتمسحش الأصل، وتسجّل إيه اللي عملته، وتنتهي بقرار.", "Because separate tools save minutes, while the full chain removes the task from your day. The criteria make sure it runs safely: it doesn’t wipe originals, it logs what it did, and it ends with a decision."),
        ],
        mech: [
          L("how", "الخطوات العشر هي المستويات التلاتة متصلة: **التشغيل** (مراقبة، قراءة، تنظيف) ← **التحليل** (جودة، محرك، مشاكل، مؤشرات) ← **العرض** (رسوم، صفحة، إرسال). كل خطوة وحدة مستقلة تقدر تختبرها لوحدها.", "The ten steps are the three levels connected: **run** (watch, read, clean) → **analysis** (quality, engine, problems, KPIs) → **reporting** (charts, page, send). Each step is an independent module testable on its own."),
          L("inside", "لاحظ إن قائمة التسليم بتطلب **مسار مجرب لاسترجاع النسخة اللي فاتت**: الأتمتة الناضجة بتفترض إنها هتغلط يوم، فبتجهز طريق الرجوع من بدري.", "Note the checklist asks for **a tested path to restore the previous version**: mature automation assumes it will fail one day and prepares the way back in advance."),
          L("link", "ده «النظام» في صورته الأولى؛ في نفس الوحدة بيتحوّل لتطبيق على جهازك ([[w5]])، والوحدة الأخيرة بتعمّمه لنظام بطبقات خمس وشريحة عمودية ([[s1]]، [[s2]]).", "This is the “system” in its first form; later in this unit it becomes an app on your machine ([[w5]]), and the last unit generalises it into five layers and a vertical slice ([[s1]], [[s2]])."),
        ],
        practice: [
          L("example", "**قسم الجودة**: كل يوم ملفات فحص من تلات خطوط بتوصل لمجلد مشترك. السلسلة بتقراهم، بتستبعد الصفوف التالفة وتسجّل السبب، بتحسب نسبة العيوب لكل خط، بتكشف أي خط عدّى الحد، وبتبني صفحة رابطها يتبعت لمدير الجودة.", "**Quality department**: inspection files from three lines land daily in a shared folder. The chain reads them, excludes corrupt rows and logs why, computes the defect rate per line, flags any line over the limit, and builds a page whose link goes to the quality manager."),
          L("apply", "حدد مستواك من الجدول المرجعي، واتبع الخطوة الجاية في الكتاب: اختار مهمة صغيرة، صف عناصرها الخمسة ([[y1]])، واستخدم Prompt بناء أداة الأتمتة حرفيًا.", "Find your level in the reference table and follow the book’s next step: pick a small task, describe its five elements ([[y1]]), and use the automation-tool prompt word for word."),
        ],
        adv: [
          L("mistakes", "- **بناء الخطوات العشر دفعة واحدة**: ابني وحدة، اختبرها، وبعدين اللي بعدها.\n- **اعتماد السلسلة من غير مقارنة شهر كامل** بالمخرج بالإيد.\n- **من غير توثيق**: السلسلة بتتوقف لما صاحبها يغيب.", "- **Building all ten steps at once**: build a module, test it, then the next.\n- **Adopting the chain without comparing a full month** with the manual output.\n- **No documentation**: the chain dies when its owner is away."),
          L("whennot", "لو محتاج رقم واحد مرة في الشهر، السلسلة الكاملة مبالغة؛ أداة صغيرة أو حتى معادلة إكسل تكفي.", "If you need one number once a month, the full chain is overkill; a small tool or even an Excel formula will do."),
        ],
      },
    },
    {
      id: "b1", unit: "u1", pages: [17, 20], diff: 1, min: 10, related: ["y4", "p9", "w1", "m1"], pre: ["f8"],
      title: { ar: "من ملفات كتير لجدول واحد تثق فيه", en: "From many files to one table you can trust" },
      sum: { ar: "تجميع ملفات بأشكال مختلفة في جدول واحد، وفحصه وتنضيفه بقواعد مكتوبة، وربطه بالشيتات الصغيرة، ولما الملف يكبر على إكسل.", en: "Combining differently shaped files into one table, checking and cleaning it by written rules, linking it to small sheets, and what to do when a file outgrows Excel." },
      book: [
        bp(17, "المهارة المطلوبة مش كتابة الكود، المهارة **وصف العملية بدقة**: الملفات اللي داخلة، والقواعد، وشكل النتيجة، والاختبارات. والأداة تشتغل على نسخة، وتكتب سجل، وتوقف برسالة واضحة.", "The skill isn't writing code but **describing the process precisely**: the input files, the rules, the result's shape and the tests. The tool works on a copy, writes a log and stops with a clear message."),
        bp(20, "**الجودة الأول**: قبل أي تحليل، افحص البيانات: القيم الناقصة، والتكرار، والوحدات، والأرقام الغريبة. التحليل على بيانات فيها أخطاء بيطلّع نتيجة شكلها مقنع وهي غلط.", "**Quality first**: before any analysis, check the data: missing values, duplicates, units and odd figures. Analysis on flawed data gives a convincing result that is wrong."),
      ],
      levels: {
        simple: [
          L("what", "تجميع البيانات يعني إنك تحط ملفات كتير بنفس المعنى في **جدول واحد**: بعد ما تتفق على شكل واحد للأعمدة، وتحط الملفات تحت بعض بعمود «المصدر»، وتفحصها وتنضّفها بقواعد مكتوبة، وتربطها بالشيتات الصغيرة.", "Combining data means putting many files that mean the same thing into **one table**: after agreeing on one column shape, you stack the files with a “Source” column, check and clean them by written rules, and link them to the small sheets."),
          L("why", "لأن السؤال المهم بييجي دايمًا على كل البيانات مع بعض: كل الفروع، وكل الشهور. ولو التجميع حصل بالإيد أو من غير فحص، الإجمالي بيطلع غلط وما حدش بيعرف ليه.", "Because the important question always spans all the data: every branch, every month. If combining happens by hand or without checks, the total comes out wrong and nobody knows why."),
        ],
        mech: [
          L("how", "- **القالب**: الأعمدة المطلوبة بأسمائها وأنواعها.\n- **التجميع**: كل ملف يتطابق مع القالب ويتحط تحت اللي قبله، ومعاه عمود «المصدر».\n- **الفحص**: الناقص، والمتكرر، والأرقام الشاذة، والتواريخ اللي برّه الفترة.\n- **التنضيف**: قواعد مكتوبة على نسخة، وكل تعديل في السجل.\n- **الربط**: بالكود مع الشيتات الصغيرة، وشيت لوحده للي ما اتربطش.\n- **المطابقة**: عدد الصفوف وإجمالي القيمة في الجدول النهائي = مجموعهم في المصادر، وأي فرق متفسّر.", "- **Template**: the required columns with names and types.\n- **Stack**: each file is matched to the template and placed under the previous one, with a “Source” column.\n- **Check**: missing, duplicated, outliers, out-of-range dates.\n- **Clean**: written rules applied to a copy, every change logged.\n- **Link**: by code to the small sheets, with a separate sheet for what didn't link.\n- **Reconcile**: the final row count and total value = their sums across the sources, with every gap explained."),
          L("inside", "إكسل بيقف عند حوالي مليون صف في الشيت، وبيتقل قبلها بكتير. علشان كده الشغل التقيل بيحصل في برنامج صغير برّه إكسل يكتبهولك الذكاء الاصطناعي: يقرا الملفات صف ورا صف، ويطلّع النتيجة الصغيرة بس، وهي اللي بتفتح في إكسل.", "Excel stops at about a million rows per sheet and slows down long before that. So the heavy work happens in a small program outside Excel that AI writes for you: it reads the files row by row and outputs only the small result, which is what opens in Excel."),
          L("link", "ده امتداد مباشر للأدوات اللي بنيناها في [[f8]]، بس على ملفات أشكالها مختلفة وأكبر. والدرس اللي بعده [[y4]] بيدخل في فحص الجودة بالتفصيل.", "This extends the tools we built in [[f8]] directly, but to files that are larger and shaped differently. The next lesson, [[y4]], goes into quality checking in detail."),
        ],
        practice: [
          L("example", "مشرف مبيعات عنده ٣٦ ملف شهري من تلات فروع، وملف ربع فيه ٣٠٠ ألف صف لمبيعات الجملة. بعد القالب والتجميع والفحص والتنضيف، طلع جدول واحد فيه ٤١٢ ألف صف وتقرير جودة. والصفوف والمبيعات مطابقين للمصدر، والفرق الوحيد ٣٤٠ صف متكرر قيمتهم ١٨٬٦٠٠ جنيه، ومتسجّلين في السجل.", "A sales supervisor has 36 monthly files from three branches and a 300,000-row quarter file of wholesale sales. After the template, stacking, checking and cleaning, he gets one 412,000-row table and a quality report. Rows and sales match the source; the only gap is 340 duplicate rows worth 18,600 pounds, recorded in the log."),
          L("apply", "اختار تلات ملفات حقيقية من شغلك بنفس المعنى. اكتب القالب الأول، وبعدين استخدم الـ Prompt الجاهز تحت علشان تجمعهم بعمود «المصدر» وتطلب تقرير جودة قبل أي تحليل.", "Pick three real files from your work that mean the same thing. Write the template first, then use the ready Prompt below to combine them with a “Source” column and ask for a quality report before any analysis."),
        ],
        adv: [
          L("mistakes", "- تجمّع الملفات زي ما هي من غير قالب، فالأعمدة تتلخبط في صمت.\n- تنسى عمود «المصدر»، فما تعرفش ترجع للأصل.\n- تحلل قبل ما تفحص.\n- تمسح الصفوف اللي ما اتربطتش بدل ما تراجعها.\n- ما تطابقش عدد الصفوف والإجمالي بالمصدر.", "- Stacking files as they are without a template, so columns scramble silently.\n- Forgetting the “Source” column, so you can't trace back.\n- Analysing before checking.\n- Deleting rows that didn't link instead of reviewing them.\n- Not reconciling the row count and the total with the source."),
          L("whennot", "لو الملفات قليلة وبتتجمع مرة واحدة في السنة، معادلة أو Power Query كفاية من غير أداة. ولو البيانات حساسة، ما ترفعهاش لأداة على النت إلا لو سياسة شركتك بتسمح.", "If the files are few and combined once a year, a formula or Power Query is enough without a tool. And if the data is sensitive, don't upload it to an online tool unless your company's policy allows it."),
        ],
      },
    },
  ]);
})(window.ACADEMY = window.ACADEMY || {});
